{
  "scenarios": [
    {
      "id": "T1-POSTINGS-001",
      "operation": {
        "method": "POST",
        "path": "/transaction-postings"
      },
      "category": "boundary",
      "purpose": "Representar o limite inferior permitido para dailyTransactions: nenhum registro.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": [],
          "cardCrossReference": "XREFFILE",
          "accounts": "ACCTFILE",
          "categoryBalances": "TCATBALF",
          "transactionOutput": "TRANFILE",
          "rejectionOutput": "DALYREJS"
        }
      },
      "expectedFromContract": {
        "request": "O array vazio é permitido e todos os bindings atendem ao schema de string não vazia.",
        "responses": {
          "200": {
            "condition": "Se a invocação concluir normalmente.",
            "required": [
              "outcome",
              "diagnostics",
              "processedCount",
              "rejectedCount",
              "transactionsWritten",
              "rejections"
            ],
            "outcome": "completed",
            "diagnostics": "Array de strings.",
            "processedCount": 0,
            "rejectedCount": 0,
            "transactionsWritten": [],
            "rejections": [],
            "returnCode": "Opcional; não há obrigação de retornar zero."
          },
          "500": {
            "condition": "Se a execução não concluir normalmente, inclusive por falha de abertura ou fechamento.",
            "schema": "#/components/schemas/FailedRun",
            "required": [
              "outcome",
              "diagnostics"
            ],
            "outcome": "failed"
          }
        },
        "effects": "A entrada vazia não impede inicialização dos arquivos abertos OUTPUT; não há garantia de preservação de seu conteúdo anterior."
      },
      "limitations": [
        "Os nomes de arquivos do contrato são usados apenas como identificadores opacos candidatos; não há evidência de que esses bindings existam.",
        "Não se pressupõe conteúdo dos arquivos persistentes.",
        "O cenário não cobre validação nem postagem de registros não vazios.",
        "Não há configuração de codificação que permita assumir uma representação display numérica."
      ]
    },
    {
      "id": "T1-POSTINGS-002",
      "operation": {
        "method": "POST",
        "path": "/transaction-postings"
      },
      "category": "negative",
      "purpose": "Representar ausência do corpo obrigatório.",
      "request": {
        "bodyKind": "absent"
      },
      "expectedFromContract": {
        "request": "Não satisfaz requestBody.required: true.",
        "response": "O contrato não define status nem schema de resposta específicos para ausência de corpo; não é inferível um status 400, 422 ou 500 para essa violação."
      },
      "limitations": [
        "Candidato deliberadamente inválido perante o contrato.",
        "Não há política contratual de validação HTTP que determine a resposta observável."
      ]
    },
    {
      "id": "T1-POSTINGS-003",
      "operation": {
        "method": "POST",
        "path": "/transaction-postings"
      },
      "category": "negative",
      "purpose": "Representar um DatasetBinding abaixo do comprimento mínimo permitido.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": [],
          "cardCrossReference": "",
          "accounts": "ACCTFILE",
          "categoryBalances": "TCATBALF",
          "transactionOutput": "TRANFILE",
          "rejectionOutput": "DALYREJS"
        }
      },
      "expectedFromContract": {
        "request": "cardCrossReference viola DatasetBinding.minLength: 1.",
        "response": "Não há resposta de validação especificada para essa violação. Uma string vazia inválida não deve ser confundida com um binding não vazio cujo recurso esteja indisponível."
      },
      "limitations": [
        "Candidato deliberadamente inválido.",
        "Os demais identificadores são candidatos derivados dos nomes do contrato, sem provisionamento estabelecido.",
        "Não se infere diagnóstico, execução do programa ou status HTTP."
      ]
    },
    {
      "id": "T1-POSTINGS-004",
      "operation": {
        "method": "POST",
        "path": "/transaction-postings"
      },
      "category": "negative",
      "purpose": "Representar dailyTransactions com tipo diferente do array exigido.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "dailyTransactions": null,
          "cardCrossReference": "XREFFILE",
          "accounts": "ACCTFILE",
          "categoryBalances": "TCATBALF",
          "transactionOutput": "TRANFILE",
          "rejectionOutput": "DALYREJS"
        }
      },
      "expectedFromContract": {
        "request": "null não satisfaz o tipo array de TransactionRecords.",
        "response": "O contrato não especifica resposta para erro de tipo no request."
      },
      "limitations": [
        "Candidato deliberadamente inválido; null não representa um arquivo sequencial vazio.",
        "Não há garantia de disponibilidade dos bindings nem de comportamento da validação de transporte."
      ]
    },
    {
      "id": "T1-INTEREST-001",
      "operation": {
        "method": "POST",
        "path": "/interest-transaction-generations"
      },
      "category": "positive",
      "purpose": "Representar uma solicitação válida em schema com o prefixo de dez caracteres exemplificado no contrato.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionIdPrefix": "2022071800",
          "categoryBalances": "TCATBALF",
          "cardCrossReference": "XREFFILE",
          "accounts": "ACCTFILE",
          "disclosureGroups": "DISCGRP",
          "transactionOutput": "TRANSACT"
        }
      },
      "expectedFromContract": {
        "request": "O prefixo tem exatamente dez caracteres e os bindings são strings não vazias.",
        "responses": {
          "200": {
            "condition": "Se a geração concluir normalmente.",
            "required": [
              "outcome",
              "diagnostics",
              "transactionsWritten"
            ],
            "outcome": "completed",
            "diagnostics": "Array de strings.",
            "transactionsWritten": "Array conforme TransactionRecords, com registros lógicos de 350 bytes transportados em base64.",
            "returnCode": "Opcional e inteiro, sem valor de sucesso fixado."
          },
          "500": {
            "condition": "Se a execução não concluir normalmente.",
            "schema": "#/components/schemas/FailedRun",
            "required": [
              "outcome",
              "diagnostics"
            ],
            "outcome": "failed"
          }
        },
        "effects": [
          "As regravações de contas ocorrem nas transições entre contas; a conta final não é regravada.",
          "Saldos por categoria são somente entrada.",
          "As transações geradas não são automaticamente postadas, combinadas ou carregadas no mestre."
        ]
      },
      "limitations": [
        "Os bindings são identificadores candidatos derivados do contrato, não fixtures provisionadas.",
        "Sem conteúdo dos arquivos vinculados, não é possível determinar quantidade, valores ou registros gerados.",
        "A disponibilidade do acesso por chave alternativa de conta não está estabelecida.",
        "A categoria positive indica conformidade do request, não garantia de HTTP 200."
      ]
    },
    {
      "id": "T1-INTEREST-002",
      "operation": {
        "method": "POST",
        "path": "/interest-transaction-generations"
      },
      "category": "boundary",
      "purpose": "Representar o comprimento fixo de dez caracteres com prefixo não correspondente a uma data, usando exemplo explícito do contrato.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionIdPrefix": "XXXXXXXXXX",
          "categoryBalances": "TCATBALF",
          "cardCrossReference": "XREFFILE",
          "accounts": "ACCTFILE",
          "disclosureGroups": "DISCGRP",
          "transactionOutput": "TRANSACT"
        }
      },
      "expectedFromContract": {
        "request": "O prefixo satisfaz simultaneamente minLength: 10 e maxLength: 10. Não há restrição de data ISO nem validação de calendário.",
        "responses": {
          "200": {
            "condition": "Se a geração concluir normalmente.",
            "required": [
              "outcome",
              "diagnostics",
              "transactionsWritten"
            ],
            "outcome": "completed",
            "diagnostics": "Array de strings.",
            "transactionsWritten": "Array conforme TransactionRecords."
          },
          "500": {
            "condition": "Se a execução não concluir normalmente.",
            "schema": "#/components/schemas/FailedRun",
            "outcome": "failed",
            "diagnostics": "Array obrigatório de strings."
          }
        },
        "generation": "Se houver transação gerada, seu identificador usa o parâmetro de dez caracteres seguido do contador de seis dígitos iniciado em 000001."
      },
      "limitations": [
        "Não se pressupõe existência de saldos, taxas não nulas ou transações geradas.",
        "Os nomes usados como bindings não comprovam disponibilidade de recursos.",
        "O comportamento de overflow do sufixo não está resolvido pelo contrato.",
        "O mapeamento para dez bytes depende da codificação do ambiente."
      ]
    },
    {
      "id": "T1-INTEREST-003",
      "operation": {
        "method": "POST",
        "path": "/interest-transaction-generations"
      },
      "category": "negative",
      "purpose": "Representar prefixo com nove caracteres, imediatamente abaixo do comprimento obrigatório.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionIdPrefix": "XXXXXXXXX",
          "categoryBalances": "TCATBALF",
          "cardCrossReference": "XREFFILE",
          "accounts": "ACCTFILE",
          "disclosureGroups": "DISCGRP",
          "transactionOutput": "TRANSACT"
        }
      },
      "expectedFromContract": {
        "request": "transactionIdPrefix viola minLength: 10.",
        "response": "Não há status ou corpo de erro de validação definido para esse comprimento inválido."
      },
      "limitations": [
        "Candidato deliberadamente inválido perante o schema HTTP.",
        "O fato de o programa não inspecionar o campo de comprimento do parâmetro não elimina a restrição do request.",
        "Não se infere truncamento, preenchimento ou execução."
      ]
    },
    {
      "id": "T1-INTEREST-004",
      "operation": {
        "method": "POST",
        "path": "/interest-transaction-generations"
      },
      "category": "negative",
      "purpose": "Representar prefixo com onze caracteres, imediatamente acima do comprimento obrigatório.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactionIdPrefix": "XXXXXXXXXXX",
          "categoryBalances": "TCATBALF",
          "cardCrossReference": "XREFFILE",
          "accounts": "ACCTFILE",
          "disclosureGroups": "DISCGRP",
          "transactionOutput": "TRANSACT"
        }
      },
      "expectedFromContract": {
        "request": "transactionIdPrefix viola maxLength: 10.",
        "response": "Não há status ou corpo de erro de validação definido para esse comprimento inválido."
      },
      "limitations": [
        "Candidato deliberadamente inválido.",
        "O contrato não autoriza esperar truncamento automático para dez caracteres.",
        "Não se pressupõe disponibilidade dos bindings."
      ]
    },
    {
      "id": "T1-REPORTS-001",
      "operation": {
        "method": "POST",
        "path": "/transaction-reports"
      },
      "category": "boundary",
      "purpose": "Representar arrays vazios, incluindo DATEPARM vazio, que explicitamente dispensa o processamento das transações.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": [],
          "cardCrossReference": "CARDXREF",
          "transactionTypes": "TRANTYPE",
          "transactionCategories": "TRANCATG",
          "reportOutput": "TRANREPT"
        }
      },
      "expectedFromContract": {
        "request": "Ambos os arrays vazios são permitidos.",
        "responses": {
          "200": {
            "condition": "Se a execução concluir normalmente.",
            "required": [
              "outcome",
              "diagnostics",
              "reportRecords"
            ],
            "outcome": "completed",
            "diagnostics": "Array de strings.",
            "reportRecords": [],
            "returnCode": "Opcional e inteiro, sem obrigação de valor zero."
          },
          "500": {
            "condition": "Se a execução não concluir normalmente, inclusive por falha de abertura ou fechamento.",
            "schema": "#/components/schemas/FailedRun",
            "required": [
              "outcome",
              "diagnostics"
            ],
            "outcome": "failed"
          }
        },
        "effects": "DATEPARM vazio faz pular o processamento e deixa a saída aberta sem registros de relatório. A operação não altera registros dos mestres de entrada."
      },
      "limitations": [
        "Os bindings são candidatos baseados nos nomes do contrato; sua existência não está estabelecida.",
        "A expectativa de relatório vazio decorre de DATEPARM vazio, não de uma garantia geral para transactions vazio.",
        "Não são cobertos filtros por datas, agrupamento, paginação ou totais.",
        "Não há pressuposto de reversão da inicialização da saída em caso de falha."
      ]
    },
    {
      "id": "T1-REPORTS-002",
      "operation": {
        "method": "POST",
        "path": "/transaction-reports"
      },
      "category": "negative",
      "purpose": "Representar omissão de dateParameterRecords, distinguindo campo ausente de array vazio permitido.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "cardCrossReference": "CARDXREF",
          "transactionTypes": "TRANTYPE",
          "transactionCategories": "TRANCATG",
          "reportOutput": "TRANREPT"
        }
      },
      "expectedFromContract": {
        "request": "Viola a presença obrigatória de dateParameterRecords.",
        "response": "O contrato não define resposta para omissão de propriedade obrigatória.",
        "default": "Não há valor padrão contratual que converta a omissão em array vazio."
      },
      "limitations": [
        "Candidato deliberadamente inválido.",
        "Não é inferível que o programa seja executado ou que produza relatório vazio.",
        "Não se infere status HTTP de validação."
      ]
    },
    {
      "id": "T1-REPORTS-003",
      "operation": {
        "method": "POST",
        "path": "/transaction-reports"
      },
      "category": "negative",
      "purpose": "Representar dateParameterRecords com tipo incorreto sem fabricar conteúdo de registros brutos.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": "",
          "cardCrossReference": "CARDXREF",
          "transactionTypes": "TRANTYPE",
          "transactionCategories": "TRANCATG",
          "reportOutput": "TRANREPT"
        }
      },
      "expectedFromContract": {
        "request": "dateParameterRecords deve ser array; uma string vazia não satisfaz esse tipo.",
        "response": "O contrato não especifica status nem schema para essa falha de validação."
      },
      "limitations": [
        "Candidato deliberadamente inválido.",
        "Uma string vazia não equivale a DATEPARM vazio nem a um registro de 80 bytes.",
        "Não se pressupõe coerção de tipos pelo transporte."
      ]
    },
    {
      "id": "T1-REPORTS-004",
      "operation": {
        "method": "POST",
        "path": "/transaction-reports"
      },
      "category": "negative",
      "purpose": "Representar reportOutput abaixo do comprimento mínimo de DatasetBinding.",
      "request": {
        "bodyKind": "json",
        "bodyJson": {
          "transactions": [],
          "dateParameterRecords": [],
          "cardCrossReference": "CARDXREF",
          "transactionTypes": "TRANTYPE",
          "transactionCategories": "TRANCATG",
          "reportOutput": ""
        }
      },
      "expectedFromContract": {
        "request": "reportOutput viola DatasetBinding.minLength: 1.",
        "response": "Não há resposta de validação definida. A regra de falha de execução para recursos ausentes ou inacessíveis não determina a resposta para uma string inválida no schema."
      },
      "limitations": [
        "Candidato deliberadamente inválido.",
        "Não se infere abertura do arquivo, diagnóstico de status ou HTTP 500.",
        "A diversidade gerada fica limitada a entradas vazias e violações estruturais, sem fixtures de arquivos persistentes ou codificação de registros fornecidas."
      ]
    }
  ]
}
